    ('66666666-6666-6666-6666-666666666662', '33333333-3333-3333-3333-333333333333', 'Десерты',          2),
    ('66666666-6666-6666-6666-666666666663', '33333333-3333-3333-3333-333333333333', 'Салаты',           3),
    ('66666666-6666-6666-6666-666666666664', '33333333-3333-3333-3333-333333333333', 'Горячее',          4),
    ('66666666-6666-6666-6666-666666666665', '33333333-3333-3333-3333-333333333333', 'Холодные напитки', 5),
    ('66666666-6666-6666-6666-666666666666', '33333333-3333-3333-3333-333333333333', 'Гарниры',          6)
ON CONFLICT (id) DO UPDATE
    SET name = EXCLUDED.name,
        sort_order = EXCLUDED.sort_order,
        deleted = FALSE;

